package com.giftmarket.admin.controller;import com.giftmarket.admin.dto.response.*;import com.giftmarket.admin.service.AdminExchangeService;import com.giftmarket.global.response.ApiResponse;import com.giftmarket.order.entity.*;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;@Validated @RestController @RequestMapping("/api/admin/exchanges") @RequiredArgsConstructor public class AdminExchangeController{private final AdminExchangeService service;@GetMapping public ApiResponse<AdminExchangePageResponse>all(@AuthenticationPrincipal Long adminId,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)ExchangeRequestStatus status,@RequestParam(required=false)ExchangeResponsibility responsibility){return ApiResponse.success(service.getExchanges(adminId,page,size,keyword,status,responsibility));}@GetMapping("/{id}")public ApiResponse<AdminExchangeDetailResponse>one(@AuthenticationPrincipal Long adminId,@PathVariable Long id){return ApiResponse.success(service.getExchange(adminId,id));}}
